//! plot stamps its marks along the run.
//!
//! ```text
//! cargo run --example tmp_dash_marks -- <drawing.pid> <reference.pdf>
//! ```

use std::path::Path;

use pid_parse::style_link::line_styles_for_document;
use pid_parse::{build_normalized_geometry, PidGraphicKind, PidParser};
use pid_plot::read::read_plot;

type Stroke = ([f64; 2], [f64; 2]);

fn length(a: [f64; 2], b: [f64; 2]) -> f64 {
    (b[0] - a[0]).hypot(b[1] - a[1])
}

fn line_distance(point: [f64; 2], a: [f64; 2], b: [f64; 2]) -> f64 {
    let (dx, dy) = (b[0] - a[0], b[1] - a[1]);
    let square = dx * dx + dy * dy;
    if square <= 1e-12 {
        return (point[0] - a[0]).hypot(point[1] - a[1]);
    }
    let t = (((point[0] - a[0]) * dx + (point[1] - a[1]) * dy) / square).clamp(0.0, 1.0);
    (point[0] - (a[0] + t * dx)).hypot(point[1] - (a[1] + t * dy))
}

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let (pid, pdf) = (&args[0], &args[1]);
    let doc = PidParser::new().parse_file(Path::new(pid)).unwrap();
    let geometry = build_normalized_geometry(&doc);
    let styles = line_styles_for_document(&doc);
    let plot = read_plot(&std::fs::read(pdf).unwrap()).unwrap();
    let plot_segments: Vec<Stroke> = plot
        .segments
        .iter()
        .map(|segment| (segment.start_mm, segment.end_mm))
        .collect();
    // A complex-dash mark is a short 45° stroke; nothing else on these sheets is
    // 3–4 mm long and diagonal at every stamp.
    let marks: Vec<Stroke> = plot_segments
        .iter()
        .copied()
        .filter(|(a, b)| (3.0..=4.2).contains(&length(*a, *b)))
        .collect();

    for entity in &geometry.entities {
        let (Some(stream), Some(oid)) = (entity.source.stream_path.as_ref(), entity.graphic_oid) else {
            continue;
        };
        let Some(style) = styles.get(&(stream.clone(), oid)) else {
            continue;
        };
        let Some(complex) = style.complex_dash.as_ref() else {
            continue;
        };
        let path: Vec<[f64; 2]> = match &entity.kind {
            PidGraphicKind::Line { start, end } => {
                vec![[start.x * 1000.0, start.y * 1000.0], [end.x * 1000.0, end.y * 1000.0]]
            }
            PidGraphicKind::Polyline { points, .. } => points
                .iter()
                .map(|point| [point.x * 1000.0, point.y * 1000.0])
                .collect(),
            _ => continue,
        };
        for (index, pair) in path.windows(2).enumerate() {
            let (a, b) = (pair[0], pair[1]);
            let run = length(a, b);
            if run < 2.0 {
                continue;
            }
            let period = complex.period_mm();
            let cells = (run / period).round() as usize;
            let ours: Vec<f64> = if cells <= 1 {
                vec![run]
            } else {
                let step = run / cells as f64;
                (0..cells).map(|cell| (cell as f64 + 0.5) * step).collect()
            };
            let u = [(b[0] - a[0]) / run, (b[1] - a[1]) / run];
            let mut theirs: Vec<f64> = Vec::new();
            for (c, d) in &marks {
                if line_distance(*c, a, b) > 8.0 || line_distance(*d, a, b) > 8.0 {
                    continue;
                }
                let mid = [(c[0] + d[0]) / 2.0, (c[1] + d[1]) / 2.0];
                let t = (mid[0] - a[0]) * u[0] + (mid[1] - a[1]) * u[1];
                if t < -4.0 || t > run + 4.0 {
                    continue;
                }
                theirs.push(t);
            }
            theirs.sort_by(f64::total_cmp);
            if theirs.is_empty() {
                continue;
            }
            println!(
                "oid {oid} seg {}/{}  L {run:6.2}  p {period:.3}  L/p {:5.3}  cells {}  step {:6.3}",
                index + 1,
                path.len() - 1,
                run / period,
                cells,
                run / cells.max(1) as f64
            );
            println!(
                "    ours  {:<44}  theirs {}",
                ours.iter().map(|t| format!("{t:6.2}")).collect::<Vec<_>>().join(" "),
                theirs.len()
            );
            println!(
                "    ref   {:<44}",
                theirs.iter().map(|t| format!("{t:6.2}")).collect::<Vec<_>>().join(" ")
            );
        }
    }
}
