{"kind":"tool","id":"biojUQpqRyM","toolName":"write_file","input":{"path":"examples/tmp_body_primitives.rs","instructions":"Temporary probe dumping template symbol-definition primitives.","content":"//! Temporary: dump every symbol definition in a template `.igr` at full
//! precision, so the title-block wave's body can be compared with the print.

use pid_parse::symbol_library::SymbolPrimitive;
use pid_parse::{ParseOptions, PidParser, build_normalized_geometry};

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let Some(path) = std::env::args().nth(1) else {
        eprintln!("usage: tmp_body_primitives <a.igr>");
        return Ok(());
    };
    let doc = PidParser::with_options(ParseOptions::geometry()).parse_file(&path)?;
    let geometry = build_normalized_geometry(&doc);
    for definition in &geometry.symbol_definitions {
        println!(
            "\nJSite{} JSheet{}  {} primitives, layers {:?}",
            definition.reference.site,
            definition.reference.sheet,
            definition.primitives.len(),
            definition.layers
        );
        for (index, primitive) in definition.primitives.iter().enumerate() {
            let layer = definition
                .primitive_layers
                .get(index)
                .copied()
                .unwrap_or_default();
            let shown = definition.layer_is_displayed(layer);
            match primitive {
                SymbolPrimitive::Arc {
                    center,
                    radius,
                    start_angle,
                    end_angle,
                    clockwise,
                } => println!(
                    "  [{index}] layer {layer} shown {shown}  arc c=({:.9},{:.9}) r={:.9} a0={:.9} a1={:.9} cw={clockwise}",
                    center.0, center.1, radius, start_angle, end_angle
                ),
                SymbolPrimitive::Line { start, end } => println!(
                    "  [{index}] layer {layer} shown {shown}  line ({:.9},{:.9})->({:.9},{:.9})",
                    start.0, start.1, end.0, end.1
                ),
                SymbolPrimitive::Circle { center, radius } => println!(
                    "  [{index}] layer {layer} shown {shown}  circle c=({:.9},{:.9}) r={:.9}",
                    center.0, center.1, radius
                ),
                other => println!("  [{index}] layer {layer} shown {shown}  {other:?}"),
            }
        }
    }
