+//! Scratch probe: compare the A0 page's furniture lettering with the A0
+//! reference plot.
+
+use std::path::PathBuf;
+
+use pid_plot::fonts::{font_dirs, prepare_fonts};
+use pid_plot::model::lay_out_drawing;
+use pid_plot::read::read_plot;
+use pid_plot::write::{PlotFont, write_plot};
+
+fn main() {
+    let corpus = PathBuf::from(r"D:\work\cad\PID自研软件验证");
+    let name = "I井场 注采阀组工艺及自控流程图";
+
+    let reference = std::fs::read(corpus.join(format!("{name}.pdf"))).unwrap();
+    let ink = read_plot(&reference).unwrap();
+    println!("reference page {:?}", ink.page_mm);
+    println!("reference spans in the title block:");
+    for span in &ink.spans {
+        if span.origin_mm[0] > 1030.0 && span.origin_mm[1] < 90.0 {
+            println!(
+                "  {origin:.2?} w={advance:.2} h={height:.2} {text:?}",
+                origin = span.origin_mm,
+                advance = span.advance_mm,
+                height = span.height_mm,
+                text = span.text
+            );
+        }
+    }
+
+    for (label, pid, x0) in [
+        ("A0", name, 1030.0),
+        ("A1", "集注站 凝析油闪蒸单元 一级闪蒸分离器B工艺及自控流程图", 682.0),
+    ] {
+        let drawing = corpus.join(format!("{pid}.pid"));
+        let model = lay_out_drawing(&drawing, &corpus).unwrap();
+        let dirs = font_dirs(Some(&corpus));
+        let prepared = prepare_fonts(&[&model], &dirs).unwrap();
+        let fonts: Vec<PlotFont<'_>> = prepared
+            .iter()
+            .map(|face| PlotFont {
+                key: &face.key,
+                bytes: &face.bytes,
+            })
+            .collect();
+        let pdf = write_plot(&model, &fonts).unwrap();
+        let ours = read_plot(&pdf).unwrap();
+        println!("{label} page {:?}", ours.page_mm);
+        println!("{label} spans in the title block:");
+        for span in &ours.spans {
+            if span.origin_mm[0] > x0 && span.origin_mm[1] < 90.0 {
+                println!(
+                    "  {origin:.2?} w={advance:.2} h={height:.2} {text:?}",
+                    origin = span.origin_mm,
+                    advance = span.advance_mm,
+                    height = span.height_mm,
+                    text = span.text
+                );
+            }
+        }
+    }
+}
