use std::collections::BTreeMap;
use std::path::PathBuf;

use pid_plot::model::{PaperShape, lay_out_drawing};

fn shape_len(shape: &PaperShape) -> f64 {
    match shape {
        PaperShape::Line { start_mm, end_mm } => {
            ((end_mm[0] - start_mm[0]).powi(2) + (end_mm[1] - start_mm[1]).powi(2)).sqrt()
        }
        PaperShape::Arc {
            radius_mm,
            start_angle,
            end_angle,
            clockwise,
            ..
        } => {
            let mut sweep = if *clockwise {
                start_angle - end_angle
            } else {
                end_angle - start_angle
            };
            while sweep < 0.0 {
                sweep += std::f64::consts::TAU;
            }
            while sweep > std::f64::consts::TAU {
                sweep -= std::f64::consts::TAU;
            }
            radius_mm * sweep
        }
        PaperShape::Circle { radius_mm, .. } => std::f64::consts::TAU * radius_mm,
        PaperShape::Polyline { points_mm, .. } => points_mm
            .windows(2)
            .map(|pair| {
                ((pair[1][0] - pair[0][0]).powi(2) + (pair[1][1] - pair[0][1]).powi(2)).sqrt()
            })
            .sum(),
        PaperShape::Fill { chain_mm, .. } => chain_mm
            .windows(2)
            .map(|pair| {
                ((pair[1][0] - pair[0][0]).powi(2) + (pair[1][1] - pair[0][1]).powi(2)).sqrt()
            })
            .sum(),
        PaperShape::Text { .. } => 0.0,
    }
}

fn main() {
    let mut args = std::env::args().skip(1);
    let name = args.next().expect("drawing name");
    let corpus = std::env::var_os("PID_PARSE_SELF_CHECK_DIR").map_or_else(
        || PathBuf::from(r"D:\work\cad\PID自研软件验证"),
        PathBuf::from,
    );
    let model = lay_out_drawing(&corpus.join(format!("{name}.pid")), &corpus).expect("layout");

    let mut per_symbol: BTreeMap<String, (usize, f64, BTreeMap<String, (usize, f64)>)> =
        BTreeMap::new();
    for primitive in &model.primitives {
        let Some(symbol) = primitive.symbol.as_deref() else {
            continue;
        };
        let short = symbol.rsplit(['/', '\\']).next().unwrap_or(symbol).to_string();
        if !short.to_ascii_lowercase().contains("ball valve") {
            continue;
        }
        let len = shape_len(&primitive.shape);
        let key = primitive
            .origin
            .map(|o| format!("{:.3},{:.3}", o[0], o[1]))
            .unwrap_or_else(|| "?".to_string());
        let entry = per_symbol
            .entry(short)
            .or_insert_with(|| (0, 0.0, BTreeMap::new()));
        entry.0 += 1;
        entry.1 += len;
        let spot = entry.2.entry(key).or_insert((0, 0.0));
        spot.0 += 1;
        spot.1 += len;
    }

    for (symbol, (count, total, spots)) in per_symbol {
        println!("{symbol}: {count} primitives, {total:.3} mm total, {} placements", spots.len());
        let mut rows: Vec<_> = spots.into_iter().collect();
        rows.sort_by(|a, b| b.1 .1.total_cmp(&a.1 .1));
        for (origin, (n, len)) in rows.iter().take(12) {
            println!("   at ({origin}) {n} prims  {len:.3} mm");
        }
    }
}
