{"kind":"tool","id":"dh9plGpq3-Q","toolName":"write_file","input":{"path":"D:/work/plant-code/cad/pid-parse-mission/pid-plot/examples/tmp_ball_valve_ink.rs","instructions":"Throwaway probe: per-stroke reference coverage for ball valves","content":"//! Throwaway: which Ball Valve stroke is not on reference ink.

use std::collections::BTreeMap;
use std::path::PathBuf;

use pid_plot::model::{PaperShape, lay_out_drawing};
use pid_plot::read::read_plot;

const SAMPLE_MM: f64 = 0.25;
const COVER_MM: f64 = 0.5;
const CELL_MM: f64 = 4.0;

struct Grid {
    cells: BTreeMap<(i32, i32), Vec<([f64; 2], [f64; 2])>>,
}

impl Grid {
    fn new(segments: &[([f64; 2], [f64; 2])]) -> Self {
        let mut cells: BTreeMap<(i32, i32), Vec<([f64; 2], [f64; 2])>> = BTreeMap::new();
        for &(a, b) in segments {
            let (lo, hi) = (
                [a[0].min(b[0]), a[1].min(b[1])],
                [a[0].max(b[0]), a[1].max(b[1])],
            );
            let x0 = (lo[0] / CELL_MM).floor() as i32;
            let x1 = (hi[0] / CELL_MM).floor() as i32;
            let y0 = (lo[1] / CELL_MM).floor() as i32;
            let y1 = (hi[1] / CELL_MM).floor() as i32;
            for x in x0..=x1 {
                for y in y0..=y1 {
                    cells.entry((x, y)).or_default().push((a, b));
                }
            }
        }
        Self { cells }
    }

    fn covered(&self, point: [f64; 2]) -> bool {
        let cx = (point[0] / CELL_MM).floor() as i32;
        let cy = (point[1] / CELL_MM).floor() as i32;
        for dx in -1..=1 {
            for dy in -1..=1 {
                if let Some(segs) = self.cells.get(&(cx + dx, cy + dy)) {
                    for &(a, b) in segs {
                        if segment_distance(point, a, b) <= COVER_MM {
                            return true;
                        }
                    }
                }
            }
        }
        false
    }
}

fn segment_distance(p: [f64; 2], a: [f64; 2], b: [f64; 2]) -> f64 {
    let (dx, dy) = (b[0] - a[0], b[1] - a[1]);
    let length2 = dx * dx + dy * dy;
    if length2 <= f64::EPSILON {
        return ((p[0] - a[0]).powi(2) + (p[1] - a[1]).powi(2)).sqrt();
    }
    let t = (((p[0] - a[0]) * dx + (p[1] - a[1]) * dy) / length2).clamp(0.0, 1.0);
    let q = [a[0] + t * dx, a[1] + t * dy];
    ((p[0] - q[0]).powi(2) + (p[1] - q[1]).powi(2)).sqrt()
}

fn samples(shape: &PaperShape) -> Vec<[f64; 2]> {
    let mut out = Vec::new();
    match shape {
        PaperShape::Line { start_mm, end_mm } => {
            let length = dist(*start_mm, *end_mm);
            let steps = ((length / SAMPLE_MM).ceil() as usize).max(1);
            for step in 0..=steps {
                let t = step as f64 / steps as f64;
                out.push([
                    start_mm[0] + (end_mm[0] - start_mm[0]) * t,
                    start_mm[1] + (end_mm[1] - start_mm[1]) * t,
                ]);
            }
        }
        PaperShape::Arc {
            center_mm,
            radius_mm,
            start_angle,
            end_angle,
            clockwise,
        } => {
            let mut sweep = if *clockwise {
                start_angle - end_angle
            } else {
                end_angle - start_angle
            };
            while sweep < 0.0 {
                sweep += std::f64::consts::TAU;
            }
            while sweep > std::f64::consts::TAU {
                sweep -= std::f64::consts::TAU;
            }
            let length = radius_mm * sweep;
            let steps = ((length / SAMPLE_MM).ceil() as usize).max(1);
            for step in 0..=steps {
                let t = step as f64 / steps as f64;
                let angle = start_angle + (-sweep * t);
                out.push([
                    center_mm[0] + radius_mm * angle.cos(),
                    center_mm[1] + radius_mm * angle.sin(),
                ]);
            }
        }
        PaperShape::Circle {
            center_mm,
            radius_mm,
        } => {
            let steps = ((std::f64::consts::TAU * radius_mm / SAMPLE_MM).ceil() as usize).max(1);
            for step in 0..=steps {
                let angle = std::f64::consts::TAU * step as f64 / steps as f64;
                out.push([
                    center_mm[0] + radius_mm * angle.cos(),
                    center_mm[1] + radius_mm * angle.sin(),
                ]);
            }
        }
        PaperShape::Polyline { points_mm, closed } => {
            for pair in points_mm.windows(2) {
                out.extend(samples(&PaperShape::Line {
                    start_mm: pair[0],
                    end_mm: pair[1],
                }));
            }
            if *closed && points_mm.len() > 2 {
                out.extend(samples(&PaperShape::Line {
                    start_mm: points_mm[points_mm.len() - 1],
                    end_mm: points_mm[0],
                }));
            }
        }
        PaperShape::Fill { chain_mm, .. } => out.extend(samples(&PaperShape::Polyline {
            points_mm: chain_mm.clone(),
            closed: true,
        })),
        PaperShape::Text { .. } => {}
    }
    out
}

fn dist(a: [f64; 2], b: [f64; 2]) -> f64 {
    ((b[0] - a[0]).powi(2) + (b[1] - a[1]).powi(2)).sqrt()
}

fn kind(shape: &PaperShape) -> String {
    match shape {
        PaperShape::Line { start_mm, end_mm } => {
            format!("line {:.3}", dist(*start_mm, *end_mm))
        }
        PaperShape::Arc {
            radius_mm,
            start_angle,
            end_angle,
            clockwise,
            ..
        } => {
            let mut sweep = if *clockwise {
                start_angle - end_angle
            } else {
                end_angle - start_angle
            };
            while sweep < 0.0 {
                sweep += std::f64::consts::TAU;
            }
            format!("arc r{radius_mm:.3} sweep {sweep:.3}")
        }
        PaperShape::Circle { radius_mm, .. } => format!("circle r{radius_mm:.3}"),
        PaperShape::Polyline { points_mm, .. } => format!("polyline n{}", points_mm.len()),
        PaperShape::Fill { chain_mm, .. } => format!("fill n{}", chain_mm.len()),
        PaperShape::Text { .. } => "text".to_string(),
    }
}

fn main() {
    let mut args = std::env::args().skip(1);
    let name = args.next().expect("drawing name");
    let corpus = std::env::var_os("PID_PARSE_SELF_CHECK_DIR").map_or_else(
        || PathBuf::from(r"D:\work\cad\PID自研软件验证"),
        PathBuf::from,
    );
    let model = lay_out_drawing(&corpus.join(format!("{name}.pid")), &corpus).expect("layout");
    let reference = read_plot(&std::fs::read(corpus.join(format!("{name}.pdf"))).expect("pdf"))
        .expect("read reference");
    let segments: Vec<([f64; 2], [f64; 2])> = reference
        .segments
        .iter()
        .map(|s| (s.start_mm, s.end_mm))
        .collect();
    let grid = Grid::new(&segments);

    let mut uncovered_by_kind: BTreeMap<String, (usize, f64)> = BTreeMap::new();
    let mut worst: Vec<(f64, String, String)> = Vec::new();
    let mut total = 0.0;
    let mut uncovered_total = 0.0;
    for primitive in &model.primitives {
        let Some(symbol) = primitive.symbol.as_deref() else {
            continue;
        };
        let short = symbol.rsplit(['/', '\\']).next().unwrap_or(symbol);
        if !short.to_ascii_lowercase().contains("ball valve") {
            continue;
        }
        let points = samples(&primitive.shape);
        let mut uncovered = 0.0;
        for pair in points.windows(2) {
            if !grid.covered(pair[0]) {
                uncovered += dist(pair[0], pair[1]);
            }
        }
        let length = dist_points(&points);
        total += length;
        uncovered_total += uncovered;
        let entry = uncovered_by_kind
            .entry(format!("{} · {}", short, kind(&primitive.shape)))
            .or_insert((0, 0.0));
        entry.0 += 1;
        entry.1 += uncovered;
        if uncovered > 0.3 {
            worst.push((
                uncovered,
                format!("{} {}", short, kind(&primitive.shape)),
                format!(
                    "anchor {:?} len {:.3} uncovered {:.3}",
                    points.first().copied().unwrap_or([0.0, 0.0]),
                    length,
                    uncovered
                ),
            ));
        }
    }
    println!("{name}: ball valve ink {total:.3} mm, uncovered {uncovered_total:.3} mm");
    for (kind, (count, uncovered)) in &uncovered_by_kind {
        if *uncovered > 0.05 {
            println!("  {kind}: {count} strokes, {uncovered:.3} mm uncovered");
        }
    }
    worst.sort_by(|a, b| b.0.total_cmp(&a.0));
    println!("worst strokes:");
    for (uncovered, what, detail) in worst.iter().take(15) {
        println!("  {uncovered:6.3} mm  {what}  [{detail}]");
    }
}

fn dist_points(points: &[[f64; 2]]) -> f64 {
    points.windows(2).map(|pair| dist(pair[0], pair[1])).sum()
}
"}}


