//! ink, with the paper-table stroke nearest each one.

use std::collections::BTreeMap;
use std::path::PathBuf;

use pid_plot::compare::{MaskRect, compare_plots_with_model, template_masks};
use pid_plot::fonts::{font_dirs, prepare_fonts};
use pid_plot::model::{PaperShape, lay_out_drawing};
use pid_plot::read::read_plot;
use pid_plot::write::{PlotFont, write_plot};

const COVER_MM: f64 = 0.5;
const SAMPLE_MM: f64 = 0.5;
const ATTRIB_MM: f64 = 15.0;

fn dist(a: [f64; 2], b: [f64; 2]) -> f64 {
    ((b[0] - a[0]).powi(2) + (b[1] - a[1]).powi(2)).sqrt()
}

fn segment_distance(p: [f64; 2], a: [f64; 2], b: [f64; 2]) -> f64 {
    let (dx, dy) = (b[0] - a[0], b[1] - a[1]);
    let length2 = dx * dx + dy * dy;
    if length2 <= f64::EPSILON {
        return dist(p, a);
    }
    let t = (((p[0] - a[0]) * dx + (p[1] - a[1]) * dy) / length2).clamp(0.0, 1.0);
    dist(p, [a[0] + t * dx, a[1] + t * dy])
}

fn samples_of(shape: &PaperShape) -> Vec<[f64; 2]> {
    match shape {
        PaperShape::Line { start_mm, end_mm } => vec![*start_mm, *end_mm],
        PaperShape::Arc { center_mm, radius_mm, .. } => vec![[center_mm[0] + radius_mm, center_mm[1]]],
        PaperShape::Circle {
            center_mm,
            radius_mm,
        } => vec![[
            center_mm[0] + radius_mm,
            center_mm[1] + radius_mm,
        ]],
        PaperShape::Polyline { points_mm, .. } => points_mm.clone(),
        PaperShape::Fill { chain_mm, .. } => chain_mm.clone(),
        PaperShape::Text { origin_mm, .. } => vec![*origin_mm],
    }
}

fn kind(shape: &PaperShape) -> &'static str {
    match shape {
        PaperShape::Line { .. } => "line",
        PaperShape::Arc { .. } => "arc",
        PaperShape::Circle { .. } => "circle",
        PaperShape::Polyline { .. } => "polyline",
        PaperShape::Fill { .. } => "fill",
        PaperShape::Text { .. } => "text",
    }
}

fn main() {
    let mut args = std::env::args().skip(1);
    let name = args.next().expect("drawing name");
    let corpus = std::env::var_os("PID_PARSE_SELF_CHECK_DIR").map_or_else(
        || PathBuf::from(r"D:\work\cad\PID自研软件验证"),
        PathBuf::from,
    );
    let model = lay_out_drawing(&corpus.join(format!("{name}.pid")), &corpus).expect("layout");
    let reference = read_plot(&std::fs::read(corpus.join(format!("{name}.pdf"))).expect("pdf"))
        .expect("read reference");
    let mut prepared = prepare_fonts(&[&model], &font_dirs(Some(&corpus))).expect("fonts");
    let fonts: Vec<PlotFont<'_>> = prepared
        .drain(..)
        .map(|face| PlotFont {
            key: &face.key,
            bytes: &face.bytes,
        })
        .collect();
    let pdf = write_plot(&model, &fonts).expect("write");
    let ours = read_plot(&pdf).expect("read ours");

    let template = template_masks(reference.page_mm);
    let missing: Vec<MaskRect> = model
        .missing_boxes
        .iter()
        .map(|box_| MaskRect {
            label: box_.path.clone(),
            min_mm: box_.min_mm,
            max_mm: box_.max_mm,
        })
        .collect();
    let report = compare_plots_with_model(&reference, &ours, &template, &missing, &model);
    println!(
        "{name}: coverage {:.4} extra {:.1} mm  by symbol {:?}",
        report.coverage,
        report.extra_length_mm,
        report
            .extra_outside_by_symbol
            .iter()
            .map(|group| format!("{} {:.2}", group.label, group.length_mm))
            .collect::<Vec<_>>()
    );

    let fit = &report.fit;
    let to_reference = |point: [f64; 2]| {
        [
            (point[0] - fit.translation_mm[0]) / fit.scale,
            (point[1] - fit.translation_mm[1]) / fit.scale,
        ]
    };
    let reference_segments: Vec<([f64; 2], [f64; 2])> = reference
        .segments
        .iter()
        .map(|segment| (segment.start_mm, segment.end_mm))
        .collect();

    let mut rows: Vec<(f64, String)> = Vec::new();
    for segment in &ours.segments {
        let a = to_reference(segment.start_mm);
        let b = to_reference(segment.end_mm);
        let length = dist(a, b);
        if length <= 0.0 {
            continue;
        }
        let steps = ((length / SAMPLE_MM).ceil() as usize).max(1);
        let mut uncovered = 0.0;
        let mut first: Option<[f64; 2]> = None;
        for step in 0..steps {
            let t0 = step as f64 / steps as f64;
            let t1 = (step + 1) as f64 / steps as f64;
            let point = [a[0] + (b[0] - a[0]) * t0, a[1] + (b[1] - a[1]) * t0];
            let inside_template = template.iter().any(|mask| {
                point[0] >= mask.min_mm[0]
                    && point[0] <= mask.max_mm[0]
                    && point[1] >= mask.min_mm[1]
                    && point[1] <= mask.max_mm[1]
            });
            if inside_template {
                continue;
            }
            let covered = reference_segments
                .iter()
                .any(|&(p, q)| segment_distance(point, p, q) <= COVER_MM);
            if !covered {
                uncovered += length / steps as f64;
                first.get_or_insert(point);
            }
            let _ = t1;
        }
        if uncovered <= 0.6 {
            continue;
        }
        let Some(start) = first else { continue };
        // Nearest paper-table stroke, measured in our own space.
        let our_mid = [
            (segment.start_mm[0] + segment.end_mm[0]) * 0.5,
            (segment.start_mm[1] + segment.end_mm[1]) * 0.5,
        ];
        let mut best = (f64::MAX, "图纸线".to_string());
        for primitive in &model.primitives {
            for point in samples_of(&primitive.shape) {
                let gap = dist(our_mid, point);
                if gap < best.0 && gap <= ATTRIB_MM {
                    best = (
                        gap,
                        format!(
                            "{} · {}",
                            primitive
                                .symbol
                                .as_deref()
                                .map(|symbol| symbol.rsplit(['/', '\\']).next().unwrap_or(symbol))
                                .unwrap_or("sheet"),
                            kind(&primitive.shape)
                        ),
                    );
                }
            }
        }
        rows.push((
            uncovered,
            format!(
                "{:6.2} mm at ({:.2},{:.2}) -> {:.2},{:.2}  nearest {} ({:.1} mm)",
                uncovered, start[0], start[1], b[0], b[1], best.1, best.0
            ),
        ));
    }
    rows.sort_by(|a, b| b.0.total_cmp(&a.0));
    let mut by_kind: BTreeMap<String, f64> = BTreeMap::new();
    for (uncovered, row) in &rows {
        let key = row.split("nearest ").nth(1).unwrap_or("?").to_string();
        *by_kind.entry(key).or_insert(0.0) += uncovered;
    }
    println!("  uncovered strokes: {} ({:.2} mm)", rows.len(), rows.iter().map(|r| r.0).sum::<f64>());
    for (kind, mm) in &by_kind {
        println!("    {mm:7.2} mm  {kind}");
    }
    for (_, row) in rows.iter().take(12) {
        println!("  {row}");
    }
}
