{"kind":"tool","id":"eNjihdbpIoo","toolName":"write_file","input":{"path":"pid-plot/examples/tmp_tick_pairs.rs","instructions":"Throwaway probe pairing our 45-degree tick strokes with the reference's","content":"//! TEMP: how far is each of our 45-degree tick strokes from the reference's
//! nearest one, and what does the reference ink at that place instead?

use std::path::PathBuf;

use pid_plot::read::read_plot;

type Stroke = ([f64; 2], [f64; 2]);

fn len(s: &Stroke) -> f64 {
    ((s.1[0] - s.0[0]).powi(2) + (s.1[1] - s.0[1]).powi(2)).sqrt()
}

fn angle(s: &Stroke) -> f64 {
    ((s.1[1] - s.0[1]).atan2(s.1[0] - s.0[0]).to_degrees() + 180.0) % 180.0
}

fn mid(s: &Stroke) -> [f64; 2] {
    [(s.0[0] + s.1[0]) / 2.0, (s.0[1] + s.1[1]) / 2.0]
}

fn dist(a: [f64; 2], b: [f64; 2]) -> f64 {
    ((a[0] - b[0]).powi(2) + (a[1] - b[1]).powi(2)).sqrt()
}

fn ticks(strokes: &[Stroke]) -> Vec<Stroke> {
    strokes
        .iter()
        .filter(|s| (3.0..=4.2).contains(&len(s)))
        .filter(|s| (angle(s) - 45.0).abs() <= 6.0)
        .copied()
        .collect()
}

fn main() {
    let a: Vec<String> = std::env::args().skip(1).collect();
    let read = |p: &str| {
        let ink = read_plot(&std::fs::read(PathBuf::from(p)).unwrap()).unwrap();
        ink.segments
            .iter()
            .map(|s| (s.start_mm, s.end_mm))
            .collect::<Vec<Stroke>>()
    };
    let ours = read(&a[0]);
    let reference = read(&a[1]);
    let ours_ticks = ticks(&ours);
    let ref_ticks = ticks(&reference);
    println!(
        "ours {} strokes, {} ticks; reference {} strokes, {} ticks",
        ours.len(),
        ours_ticks.len(),
        reference.len(),
        ref_ticks.len()
    );
    let mut paired = 0;
    let mut far: Vec<(f64, Stroke)> = Vec::new();
    for t in &ours_ticks {
        let d = ref_ticks
            .iter()
            .map(|r| dist(mid(t), mid(r)))
            .fold(f64::INFINITY, f64::min);
        if d <= 0.6 {
            paired += 1;
        } else {
            far.push((d, *t));
        }
    }
    println!("ours with a reference tick within 0.6 mm: {paired}");
    far.sort_by(|l, r| r.0.total_cmp(&l.0));
    println!("ours with no reference tick ({}):", far.len());
    for (d, t) in &far {
        let m = mid(t);
        let nearest_ref = reference
            .iter()
            .map(|r| (dist(m, mid(r)), *r))
            .fold((f64::INFINITY, *t), |best, c| {
                if c.0 < best.0 { c } else { best }
            });
        println!(
            "  ours ({:7.3},{:7.3}) -> ({:7.3},{:7.3})  len {:5.3} ang {:5.1}  nearest ref tick {d:6.3} mm; \
             nearest ref stroke {:.3} mm len {:.3} ang {:.1}",
            t.0[0],
            t.0[1],
            t.1[0],
            t.1[1],
            len(t),
            angle(t),
            nearest_ref.0,
            len(&nearest_ref.1),
            angle(&nearest_ref.1)
        );
    }
}
"}}


