    ],
}

CONST = {
    "CPE-SQ-A0.igr": "CPE_SQ_A0_LABELS",
    "CPE-SQ-A1.igr": "CPE_SQ_A1_LABELS",
    "CPE-SQ-A2.igr": "CPE_SQ_A2_LABELS",
    "CPECCHB-SQ-A1.igr": "CPECCHB_SQ_A1_LABELS",
    "CPECCHB-SQ-A2.igr": "CPECCHB_SQ_A2_LABELS",
    "A0-W - New.igr": "A0_W_LABELS",
    "A1-W - New.igr": "A1_W_LABELS",
}

ORDER = [
    "CPE-SQ-A0.igr",
    "CPE-SQ-A1.igr",
    "CPE-SQ-A2.igr",
    "CPECCHB-SQ-A1.igr",
    "CPECCHB-SQ-A2.igr",
    "A0-W - New.igr",
    "A1-W - New.igr",
]

HEADER = re.compile(r"^=== (.+?) — (\d+) sheets, (\d+) labels \(from ")


def sections(path):
    """file name -> list of the label literal lines the probe printed."""
    out = {}
    current = None
    for line in open(path, encoding="utf-8"):
        line = line.rstrip("\n")
        match = HEADER.match(line)
        if match:
            current = match.group(1)
            out[current] = []
        elif current is not None and line.startswith("    ("):
