    /// Primitives whose ink reaches past the page by more than `slack_mm`.
    ///
    /// This is the sheet-overhang reading, not a refusal: [`beyond_the_sheet`]
    /// drops a stroke that cannot ink the page at all, while a label whose
    /// origin sits a millimetre under the bottom edge still letters its run
    /// onto the sheet and is clipped there like a printer's. Reporting what
    /// hangs over — rather than rejecting it — is what keeps the corpus honest:
    /// 60 drawings carry exactly one such primitive (a sideways run in `N井场`
    /// whose first glyph loses 1.55 mm of its foot), and a rule that refused it
    /// would take the other nineteen glyphs with it.
    ///
    /// A text's origin is the only position its shape carries, so a run is
    /// judged by where it starts; every other shape by the points its ink
    /// reaches. `slack_mm` keeps a stroke that sits exactly on the edge out of
    /// the count.
    #[must_use]
    pub fn primitives_past_the_edge(&self, slack_mm: f64) -> Vec<&PaperPrimitive> {
        let Some(page) = self.resolved_page_mm() else {
            return Vec::new();
        };
        self.primitives
            .iter()
            .filter(|primitive| {
                shape_points(&primitive.shape)
                    .into_iter()
                    .filter(|point| finite(*point))
