        // reference line exactly between two of ours, so the nearest
        // neighbour would not be the shifted copy.
        let reference = ink(
            vec![
                line([0.0, 0.0], [80.0, 0.0]),
                line([0.0, 40.0], [80.0, 40.0]),
                line([0.0, 80.0], [80.0, 80.0]),
                line([0.0, 120.0], [80.0, 120.0]),
