                line([0.0, 50.0], [80.0, 50.0]),
                line([0.0, 90.0], [80.0, 90.0]),
                line([0.0, 130.0], [80.0, 130.0]),
            ],
            vec![],
        );
        let report = compare_plots(&reference, &ours, &[]);
        assert!(!report.fit.within_threshold, "{:?}", report.fit);
