    pub paired: usize,
    /// Of those, the ones whose width is the reference's.
    pub agreed: usize,
    /// Of those, the ones whose width is not.
    pub differed: usize,
    /// Our strokes with no reference stroke at the same place.
    pub unpaired: usize,
